import{_ as n,H as a,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"09｜接口和数据模型：让 AI 产出生成接口清单和 Schema","description":"","frontmatter":{},"headers":[{"level":2,"title":"接口和数据模型为什么要一起梳理","slug":"接口和数据模型为什么要一起梳理","link":"#接口和数据模型为什么要一起梳理","children":[]},{"level":2,"title":"资产 1：REST 接口清单","slug":"资产-1-rest-接口清单","link":"#资产-1-rest-接口清单","children":[]},{"level":2,"title":"资产 2：数据模型说明","slug":"资产-2-数据模型说明","link":"#资产-2-数据模型说明","children":[]},{"level":2,"title":"五份资产怎么用","slug":"五份资产怎么用","link":"#五份资产怎么用","children":[]},{"level":2,"title":"接口清单和数据模型之间的“校对”","slug":"接口清单和数据模型之间的-校对","link":"#接口清单和数据模型之间的-校对","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/09｜接口和数据模型：让AI产出生成接口清单和Schema.md","filePath":"ClaudeCode企业级老项目改造实战/09｜接口和数据模型：让AI产出生成接口清单和Schema.md","lastUpdated":1779815445000}'),l={name:"ClaudeCode企业级老项目改造实战/09｜接口和数据模型：让AI产出生成接口清单和Schema.md"};function i(c,s,o,t,r,d){return a(),p("div",null,[...s[0]||(s[0]=[e('<h1 id="_09-接口和数据模型-让-ai-产出生成接口清单和-schema" tabindex="-1">09｜接口和数据模型：让 AI 产出生成接口清单和 Schema <a class="header-anchor" href="#_09-接口和数据模型-让-ai-产出生成接口清单和-schema" aria-label="Permalink to &quot;09｜接口和数据模型：让 AI 产出生成接口清单和 Schema&quot;">​</a></h1><p>你好，我是 Robert。</p><p>上一讲画完了三张俯视图，系统级有了架构图、代码级有了模块图、生态级有了依赖图。三种粒度的俯视摆在 <code>docs/</code> 里，你和 AI 对这个项目有了第一层共识，通过俯视告诉你“项目长什么样”，但它没告诉你“项目怎么被调用”和“项目在处理什么数据”，而这就是本节课要讲的内容。</p><p>对应八步心法第 5 步： <strong>梳理接口和数据模型</strong>。梳理完你会拿到两份新的资产： <strong>一份 REST 接口清单</strong> 和 <strong>一份核心数据模型说明</strong>，都住进 <code>docs/</code> 里。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976182/f5a52c93790eff2e2f05bfa5c8578d52.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976182/f5a52c93790eff2e2f05bfa5c8578d52.png" alt=""></a></p><h2 id="接口和数据模型为什么要一起梳理" tabindex="-1">接口和数据模型为什么要一起梳理 <a class="header-anchor" href="#接口和数据模型为什么要一起梳理" aria-label="Permalink to &quot;接口和数据模型为什么要一起梳理&quot;">​</a></h2><p>你可能会想，接口和数据模型是两件事，为什么合在一节课讲？因为它们是 <strong>项目的门面和根基</strong>，彼此绑定。</p><ol><li><p><strong>接口是门面</strong>。外部世界通过接口和这个项目打交道。前端调什么 API、三方集成请求什么端点、运维连什么管理接口，全是接口。接口清单决定了“这个项目对外承诺了什么”。</p></li><li><p><strong>数据模型是根基</strong>。接口处理的每一个请求、返回的每一份响应，背后都对应某些数据结构的流动。Prompt 对象长什么样、Dataset 的字段有哪些、Evaluator 的结果存成什么格式，这些是项目的内部骨骼。</p></li><li><p><strong>两者绑定的原因</strong>：接口的参数和返回，90% 的情况下是数据模型的某种映射或变形。接口 <code>POST /api/prompts/create</code> 的请求体基本就是 Prompt 数据模型的子集，响应基本就是 Prompt 的一个视图。 <strong>接口和数据模型画不清楚，就看不出这个项目的真实形状</strong>。</p></li></ol><p>更重要的一点，从改造的角度看，你要加一个新功能，大概率要改三处：加一个接口、改几个数据模型字段、改对应的业务逻辑。接口清单和数据模型就是你 <strong>改动的导航地图</strong>。没有这两份资产，每次改造都要从零摸索。</p><p>所以 09 讲要让 AI 帮你一次性把这两份都梳理出来。</p><h2 id="资产-1-rest-接口清单" tabindex="-1">资产 1：REST 接口清单 <a class="header-anchor" href="#资产-1-rest-接口清单" aria-label="Permalink to &quot;资产 1：REST 接口清单&quot;">​</a></h2><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扫一下这个项目里所有的 Controller，给我整理一份 REST 接口清单。</span></span>\n<span class="line"><span>每个接口列出方法（GET/POST 等）、路径、一句话说明、主要入参、返回结构。</span></span>\n<span class="line"><span>按模块分组。保存到 docs/api-list.md。</span></span></code></pre></div><p><strong>关键点</strong>：</p><ul><li><p>“按模块分组”是让清单有组织。Spring AI Alibaba Admin 有 Prompt、Dataset、Evaluator、Experiment、Trace 几大模块，每个模块下有若干接口。分组的清单可读性远高于一张一百行的大表。</p></li><li><p>“一句话说明”强制 AI 给出人类能看懂的意图，而不是只抄 <code>@Operation</code> 注解或方法名。接口叫 <code>createPromptTemplate</code>，一句话说明应该是“创建一个新的 Prompt 模板”，让非开发同事也能看懂。</p></li><li><p>“主要入参、返回结构”要求 AI 不只列端点，还要列参数类型和返回类型，但 <strong>不要展开所有字段</strong>，只要主要的。字段细节交给数据模型那份文档。</p></li></ul><p>下面是运行出来的清单内容：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># REST 接口清单</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&amp;gt; 来源：扫描所有 Controller 源码自动整理，共 32 个 Controller。</span></span>\n<span class="line"><span>&amp;gt; 统一返回结构：`Result&amp;lt;T&amp;gt;` `{ code, message, data: T }`，分页为 `PageResult&amp;lt;T&amp;gt;` / `PagingList&amp;lt;T&amp;gt;` `{ total, list }`。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 目录</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- [1. 认证 / 账号](#1-认证--账号)</span></span>\n<span class="line"><span>- [2. Prompt 管理](#2-prompt-管理)</span></span>\n<span class="line"><span>- [3. 数据集管理](#3-数据集管理)</span></span>\n<span class="line"><span>- [4. 评估器管理](#4-评估器管理)</span></span>\n<span class="line"><span>- [5. 实验管理](#5-实验管理)</span></span>\n<span class="line"><span>- [6. 模型配置（Studio）](#6-模型配置studio)</span></span>\n<span class="line"><span>- [7. 可观测性](#7-可观测性)</span></span>\n<span class="line"><span>- [8. 应用管理](#8-应用管理)</span></span>\n<span class="line"><span>- [9. 工作流调试](#9-工作流调试)</span></span>\n<span class="line"><span>- [10. 知识库 / 文档 / 分块](#10-知识库--文档--分块)</span></span>\n<span class="line"><span>- [11. 模型 / Provider 管理](#11-模型--provider-管理)</span></span>\n<span class="line"><span>- [12. 工具 / 插件](#12-工具--插件)</span></span>\n<span class="line"><span>- [13. MCP Server](#13-mcp-server)</span></span>\n<span class="line"><span>- [14. Agent Schema](#14-agent-schema)</span></span>\n<span class="line"><span>- [15. 文件上传](#15-文件上传)</span></span>\n<span class="line"><span>- [16. API Key](#16-api-key)</span></span>\n<span class="line"><span>- [17. 工作空间](#17-工作空间)</span></span>\n<span class="line"><span>- [18. 组件服务](#18-组件服务)</span></span>\n<span class="line"><span>- [19. Chat 对话（OpenAPI）](#19-chat-对话openapi)</span></span>\n<span class="line"><span>- [20. OAuth2](#20-oauth2)</span></span>\n<span class="line"><span>- [21. 系统](#21-系统)</span></span>\n<span class="line"><span>- [22. 代码生成器（Graph Studio）](#22-代码生成器graph-studio)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 1. 认证 / 账号</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/auth`、`/console/v1/accounts`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 1.1 认证</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/auth/login` | 用户名密码登录，返回 JWT Token |</span></span>\n<span class="line"><span>| POST | `/console/v1/auth/refresh-token` | 刷新 Token |</span></span>\n<span class="line"><span>| POST | `/console/v1/auth/logout` | 退出登录，使 Token 失效 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/auth/login`**</span></span>\n<span class="line"><span>- 入参：`LoginRequest { username, password }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;TokenResponse&amp;gt;` — `{ accessToken, refreshToken, expiresIn }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/auth/refresh-token`**</span></span>\n<span class="line"><span>- 入参：`RefreshTokenRequest { refreshToken }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;TokenResponse&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/auth/logout`**</span></span>\n<span class="line"><span>- 入参：Header 携带 Token</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Void&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 1.2 账号管理</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/accounts` | 创建账号 |</span></span>\n<span class="line"><span>| GET | `/console/v1/accounts` | 分页查询账号列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/accounts/{accountId}` | 获取账号详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/accounts/{accountId}` | 更新账号信息 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/accounts/{accountId}` | 删除账号 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/accounts/change-password` | 修改密码 |</span></span>\n<span class="line"><span>| GET | `/console/v1/accounts/profile` | 获取当前登录用户信息 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/accounts`**</span></span>\n<span class="line"><span>- 入参：`Account { username, email, role, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;String&amp;gt;` — 新建账号 ID</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/console/v1/accounts`**</span></span>\n<span class="line"><span>- 入参：`BaseQuery { page, size, keyword }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PagingList&amp;lt;Account&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**PUT `/console/v1/accounts/change-password`**</span></span>\n<span class="line"><span>- 入参：`ChangePasswordRequest { oldPassword, newPassword }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;String&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 2. Prompt 管理</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/api`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/api/prompt` | 创建 Prompt |</span></span>\n<span class="line"><span>| GET | `/api/prompt` | 按 promptKey 获取 Prompt |</span></span>\n<span class="line"><span>| GET | `/api/prompts` | 分页列表 |</span></span>\n<span class="line"><span>| PUT | `/api/prompt` | 更新 Prompt |</span></span>\n<span class="line"><span>| DELETE | `/api/prompt` | 删除 Prompt |</span></span>\n<span class="line"><span>| POST | `/api/prompt/version` | 创建 Prompt 版本 |</span></span>\n<span class="line"><span>| GET | `/api/prompt/version` | 获取指定版本详情 |</span></span>\n<span class="line"><span>| GET | `/api/prompt/versions` | 版本分页列表 |</span></span>\n<span class="line"><span>| GET | `/api/prompt/template` | 获取 Prompt 模板详情 |</span></span>\n<span class="line"><span>| GET | `/api/prompt/templates` | 模板分页列表 |</span></span>\n<span class="line"><span>| POST | `/api/prompt/run` | 执行 Prompt（流式） |</span></span>\n<span class="line"><span>| GET | `/api/prompt/session` | 获取对话 Session |</span></span>\n<span class="line"><span>| DELETE | `/api/prompt/session` | 删除对话 Session |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/prompt`**</span></span>\n<span class="line"><span>- 入参：`PromptCreateRequest { promptKey, name, description, content, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Prompt&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/prompt`**</span></span>\n<span class="line"><span>- 入参：`?promptKey=xxx`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Prompt&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/prompts`**</span></span>\n<span class="line"><span>- 入参：`PromptListRequest { page, size, keyword }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PageResult&amp;lt;Prompt&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/prompt/version`**</span></span>\n<span class="line"><span>- 入参：`PromptVersionCreateRequest { promptKey, content, remark, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PromptVersion&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/prompt/version`**</span></span>\n<span class="line"><span>- 入参：`?promptKey=xxx&amp;version=xxx`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PromptVersionDetail&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/prompt/run`**</span></span>\n<span class="line"><span>- 入参：`PromptRunRequest { promptKey, version, variables, sessionId, stream }`</span></span>\n<span class="line"><span>- 返回：`Flux&amp;lt;PromptRunResponse&amp;gt;` — SSE 流式响应</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/prompt/session`**</span></span>\n<span class="line"><span>- 入参：`?sessionId=xxx`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;ChatSession&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 3. 数据集管理</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/api/dataset`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/api/dataset/dataset` | 创建数据集 |</span></span>\n<span class="line"><span>| GET | `/api/dataset/datasets` | 数据集分页列表 |</span></span>\n<span class="line"><span>| GET | `/api/dataset/dataset` | 获取数据集详情 |</span></span>\n<span class="line"><span>| PUT | `/api/dataset/dataset` | 更新数据集 |</span></span>\n<span class="line"><span>| DELETE | `/api/dataset/dataset` | 删除数据集 |</span></span>\n<span class="line"><span>| POST | `/api/dataset/datasetVersion` | 创建数据集版本 |</span></span>\n<span class="line"><span>| GET | `/api/dataset/datasetVersions` | 版本分页列表 |</span></span>\n<span class="line"><span>| PUT | `/api/dataset/datasetVersion` | 更新版本信息 |</span></span>\n<span class="line"><span>| POST | `/api/dataset/dataItem` | 创建数据项 |</span></span>\n<span class="line"><span>| GET | `/api/dataset/dataItems` | 数据项分页列表 |</span></span>\n<span class="line"><span>| GET | `/api/dataset/dataItem` | 获取单条数据项 |</span></span>\n<span class="line"><span>| PUT | `/api/dataset/dataItem` | 更新数据项 |</span></span>\n<span class="line"><span>| DELETE | `/api/dataset/dataItem` | 删除数据项 |</span></span>\n<span class="line"><span>| GET | `/api/dataset/experiments` | 关联实验列表 |</span></span>\n<span class="line"><span>| POST | `/api/dataset/dataItemFromTrace` | 从链路追踪创建数据项 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/dataset/dataset`**</span></span>\n<span class="line"><span>- 入参：`DatasetCreateRequest { name, description, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Dataset&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/dataset/datasets`**</span></span>\n<span class="line"><span>- 入参：`DatasetListRequest { page, size, keyword }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PageResult&amp;lt;Dataset&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/dataset/dataset`**</span></span>\n<span class="line"><span>- 入参：`?datasetId=123`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Dataset&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/dataset/dataItem`**</span></span>\n<span class="line"><span>- 入参：`DatasetItemCreateRequest { datasetId, items: [{ input, expectedOutput, ... }] }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;DatasetItem&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/dataset/dataItemFromTrace`**</span></span>\n<span class="line"><span>- 入参：`DataItemCreateFromTraceRequest { traceId, datasetId, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;DatasetItem&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 4. 评估器管理</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/api/evaluator`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/api/evaluator/evaluator` | 创建评估器 |</span></span>\n<span class="line"><span>| GET | `/api/evaluator/evaluators` | 评估器分页列表 |</span></span>\n<span class="line"><span>| GET | `/api/evaluator/evaluator` | 获取评估器详情 |</span></span>\n<span class="line"><span>| PUT | `/api/evaluator/evaluator` | 更新评估器 |</span></span>\n<span class="line"><span>| DELETE | `/api/evaluator/evaluator` | 删除评估器 |</span></span>\n<span class="line"><span>| POST | `/api/evaluator/evaluatorVersion` | 创建评估器版本 |</span></span>\n<span class="line"><span>| GET | `/api/evaluator/evaluatorVersions` | 版本分页列表 |</span></span>\n<span class="line"><span>| POST | `/api/evaluator/debug` | 调试评估器 |</span></span>\n<span class="line"><span>| GET | `/api/evaluator/templates` | 评估器模板列表 |</span></span>\n<span class="line"><span>| GET | `/api/evaluator/template` | 获取模板详情 |</span></span>\n<span class="line"><span>| GET | `/api/evaluator/experiments` | 关联实验列表 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/evaluator/evaluator`**</span></span>\n<span class="line"><span>- 入参：`EvaluatorCreateRequest { name, type, config, templateId, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Evaluator&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/evaluator/debug`**</span></span>\n<span class="line"><span>- 入参：`EvaluatorTestRequest { evaluatorId, input, expectedOutput }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;EvaluatorDebugResult&amp;gt;` — `{ score, passed, detail }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/evaluator/templates`**</span></span>\n<span class="line"><span>- 入参：`EvaluatorTemplateListRequest { page, size }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PageResult&amp;lt;EvaluatorTemplate&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 5. 实验管理</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/api`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/api/experiment` | 创建实验 |</span></span>\n<span class="line"><span>| GET | `/api/experiments` | 实验分页列表 |</span></span>\n<span class="line"><span>| GET | `/api/experiment` | 获取实验详情 |</span></span>\n<span class="line"><span>| GET | `/api/experiment/results` | 获取实验整体评估结果 |</span></span>\n<span class="line"><span>| GET | `/api/experiment/result` | 获取单个评估结果明细（分页） |</span></span>\n<span class="line"><span>| PUT | `/api/experiment/stop` | 停止实验 |</span></span>\n<span class="line"><span>| PUT | `/api/experiment/restart` | 重启实验 |</span></span>\n<span class="line"><span>| DELETE | `/api/experiment` | 删除实验 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/experiment`**</span></span>\n<span class="line"><span>- 入参：`ExperimentCreateRequest { name, datasetId, evaluatorIds[], promptKey, promptVersion, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Experiment&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/experiment/results`**</span></span>\n<span class="line"><span>- 入参：`?experimentId=123`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;ExperimentEvaluatorResult&amp;gt;&amp;gt;` — 每个评估器的汇总分</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/experiment/result`**</span></span>\n<span class="line"><span>- 入参：`ExperimentEvaluatorResultDetailListRequest { experimentId, evaluatorId, page, size }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PageResult&amp;lt;ExperimentEvaluatorResultDetail&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 6. 模型配置（Studio）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/api`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| GET | `/api/model/supported` | 查询支持的模型提供商列表 |</span></span>\n<span class="line"><span>| GET | `/api/models` | 模型配置分页列表 |</span></span>\n<span class="line"><span>| GET | `/api/model` | 按 ID 获取单条模型配置 |</span></span>\n<span class="line"><span>| GET | `/api/models/enabled` | 获取所有已启用的模型配置 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/model/supported`**</span></span>\n<span class="line"><span>- 入参：无</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;String&amp;gt;&amp;gt;` — 提供商名称列表，如 `[&quot;openai&quot;,&quot;dashscope&quot;,&quot;deepseek&quot;]`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/models`**</span></span>\n<span class="line"><span>- 入参：`ModelConfigQueryRequest { page, size, provider }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PageResult&amp;lt;ModelConfigResponse&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/models/enabled`**</span></span>\n<span class="line"><span>- 入参：无</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;ModelConfigResponse&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 7. 可观测性</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/api/observability`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| GET | `/api/observability/traces` | 链路列表（分页） |</span></span>\n<span class="line"><span>| GET | `/api/observability/traces/{traceId}` | 获取 Trace 详情及 Span 树 |</span></span>\n<span class="line"><span>| GET | `/api/observability/services` | 服务列表及统计 |</span></span>\n<span class="line"><span>| GET | `/api/observability/overview` | 全局概览统计 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/observability/traces`**</span></span>\n<span class="line"><span>- 入参：`TracesQueryRequest { page, size, serviceName, startTime, endTime, status }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;PageResult&amp;lt;TraceSpanDTO&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/observability/traces/{traceId}`**</span></span>\n<span class="line"><span>- 入参：`traceId` (path)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;TraceDetailDTO&amp;gt;` — 含完整 Span 树</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/observability/services`**</span></span>\n<span class="line"><span>- 入参：`ServicesQueryRequest { startTime, endTime }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;ServicesResponseDTO&amp;gt;` — `{ services: [{ name, requestCount, errorRate, avgDuration }] }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/api/observability/overview`**</span></span>\n<span class="line"><span>- 入参：`OverviewQueryRequest { startTime, endTime }` (query string)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;OverviewStatsDTO&amp;gt;` — `{ totalTraces, errorCount, avgDuration, ... }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 8. 应用管理</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/apps`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/apps` | 创建应用 |</span></span>\n<span class="line"><span>| GET | `/console/v1/apps` | 应用分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/apps/{appId}` | 获取应用详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/apps/{appId}` | 更新应用 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/apps/{appId}` | 删除应用 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/{appId}/publish` | 发布应用 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/{appId}/copy` | 复制应用 |</span></span>\n<span class="line"><span>| GET | `/console/v1/apps/{appId}/versions` | 应用版本列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/apps/{appId}/versions/{version}` | 获取指定版本详情 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/chat/completions` | 应用对话（内部调试用） |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/apps`**</span></span>\n<span class="line"><span>- 入参：`Application { name, type, description, config, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;String&amp;gt;` — 新建 appId</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/apps/{appId}/publish`**</span></span>\n<span class="line"><span>- 入参：`appId` (path)</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Void&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/apps/chat/completions`**</span></span>\n<span class="line"><span>- 入参：`AgentRequest { appId, messages[], stream, ... }`，`HttpServletResponse`</span></span>\n<span class="line"><span>- 返回：SSE 流 / JSON（取决于 stream 参数）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 9. 工作流调试</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/apps`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/workflow/debug/init` | 初始化工作流调试，返回入参定义 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/workflow/debug/run-task` | 执行调试任务 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/workflow/debug/get-task-process` | 查询任务执行进度 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/workflow/debug/resume-task` | 恢复暂停的任务 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/workflow/debug/part-graph/run-task` | 执行子图任务 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/workflow/debug/part-graph/stop-task` | 停止子图任务 |</span></span>\n<span class="line"><span>| POST | `/console/v1/apps/workflow/{appId}/run_stream` | 正式运行工作流（SSE 流） |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/apps/workflow/debug/init`**</span></span>\n<span class="line"><span>- 入参：`InitRequest { appId, version }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;TaskRunParam&amp;gt;&amp;gt;` — 入参字段定义列表</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/apps/workflow/debug/run-task`**</span></span>\n<span class="line"><span>- 入参：`TaskRunRequest { appId, inputs, nodeId }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;TaskRunResponse&amp;gt;` — `{ taskId, status }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/apps/workflow/{appId}/run_stream`**</span></span>\n<span class="line"><span>- 入参：`appId` (path)，`ApiTaskRunRequest { inputs, ... }`</span></span>\n<span class="line"><span>- 返回：`SseEmitter` — 实时事件流</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 10. 知识库 / 文档 / 分块</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/knowledge-bases`、`/console/v1/documents`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 知识库</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/knowledge-bases` | 创建知识库 |</span></span>\n<span class="line"><span>| GET | `/console/v1/knowledge-bases` | 知识库分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/knowledge-bases/{kbId}` | 获取知识库详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/knowledge-bases/{kbId}` | 更新知识库 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/knowledge-bases/{kbId}` | 删除知识库 |</span></span>\n<span class="line"><span>| POST | `/console/v1/knowledge-bases/query-by-codes` | 按 code 批量查询 |</span></span>\n<span class="line"><span>| POST | `/console/v1/knowledge-bases/retrieve` | 向量检索（RAG 召回） |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/knowledge-bases/retrieve`**</span></span>\n<span class="line"><span>- 入参：`DocumentRetrieverQuery { kbCode, query, topK, minScore }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;DocumentChunk&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 文档</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/knowledge-bases/{kbId}/documents` | 批量创建文档 |</span></span>\n<span class="line"><span>| GET | `/console/v1/knowledge-bases/{kbId}/documents` | 文档分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/knowledge-bases/{kbId}/documents/{docId}` | 获取文档详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/knowledge-bases/{kbId}/documents/{docId}` | 更新文档 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/knowledge-bases/{kbId}/documents/{docId}` | 删除文档 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/knowledge-bases/{kbId}/documents/batch-delete` | 批量删除文档 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/knowledge-bases/{kbId}/documents/{docId}/re-index` | 重新索引文档 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/knowledge-bases/{kbId}/documents`**</span></span>\n<span class="line"><span>- 入参：`CreateDocumentRequest { filePaths[], parseConfig, indexConfig }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;String&amp;gt;&amp;gt;` — 文档 ID 列表</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 文档分块</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/documents/{docId}/chunks` | 创建分块 |</span></span>\n<span class="line"><span>| GET | `/console/v1/documents/{docId}/chunks` | 分块分页列表 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/documents/{docId}/chunks/{chunkId}` | 更新分块 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/documents/{docId}/chunks/{chunkId}` | 删除分块 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/documents/{docId}/chunks/batch-delete` | 批量删除分块 |</span></span>\n<span class="line"><span>| POST | `/console/v1/documents/{docId}/chunks/preview` | 预览分块效果（不入库） |</span></span>\n<span class="line"><span>| PUT | `/console/v1/documents/{docId}/chunks/update-status` | 批量更新分块状态 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 11. 模型 / Provider 管理</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/models`、`/console/v1/providers`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 模型选择器</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| GET | `/console/v1/models/{modelType}/selector` | 按类型获取可用模型分组列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/models/enabled` | 获取已启用模型列表 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/console/v1/models/{modelType}/selector`**</span></span>\n<span class="line"><span>- 入参：`modelType` (path) — 如 `chat`、`embedding`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;ModelProviderGroup&amp;gt;&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### Provider 配置</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/providers` | 添加 Provider |</span></span>\n<span class="line"><span>| GET | `/console/v1/providers` | Provider 列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/providers/{provider}` | 获取 Provider 详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/providers/{provider}` | 更新 Provider |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/providers/{provider}` | 删除 Provider |</span></span>\n<span class="line"><span>| GET | `/console/v1/providers/protocols` | 查询支持的协议列表 |</span></span>\n<span class="line"><span>| POST | `/console/v1/providers/{provider}/models` | 为 Provider 添加模型 |</span></span>\n<span class="line"><span>| GET | `/console/v1/providers/{provider}/models` | 查询 Provider 下的模型 |</span></span>\n<span class="line"><span>| GET | `/console/v1/providers/{provider}/models/{modelId}` | 获取模型详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/providers/{provider}/models/{modelId}` | 更新模型配置 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/providers/{provider}/models/{modelId}` | 删除模型 |</span></span>\n<span class="line"><span>| GET | `/console/v1/providers/{provider}/models/{modelId}/parameter_rules` | 获取模型参数规则 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 12. 工具 / 插件</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/tools`、`/console/v1`（plugins）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 工具（内置）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/tools` | 创建工具 |</span></span>\n<span class="line"><span>| GET | `/console/v1/tools` | 全量工具列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/tools/page` | 工具分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/tools/{id}` | 获取工具详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/tools/{id}` | 更新工具 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/tools/{id}` | 删除工具 |</span></span>\n<span class="line"><span>| GET | `/console/v1/tools/search` | 按名称搜索工具 |</span></span>\n<span class="line"><span>| GET | `/console/v1/tools/plugin/{pluginId}` | 按插件 ID 查询工具 |</span></span>\n<span class="line"><span>| PATCH | `/console/v1/tools/{id}/enabled` | 启用 / 禁用工具 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**PATCH `/console/v1/tools/{id}/enabled`**</span></span>\n<span class="line"><span>- 入参：`id` (path)，`?enabled=true/false`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;Void&amp;gt;`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 插件</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/plugins` | 创建插件 |</span></span>\n<span class="line"><span>| GET | `/console/v1/plugins` | 插件分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/plugins/{pluginId}` | 获取插件详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/plugins/{pluginId}` | 更新插件 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/plugins/{pluginId}` | 删除插件 |</span></span>\n<span class="line"><span>| POST | `/console/v1/plugins/{pluginId}/tools` | 为插件添加工具 |</span></span>\n<span class="line"><span>| GET | `/console/v1/plugins/{pluginId}/tools` | 插件工具列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/plugins/{pluginId}/tools/{toolId}` | 获取插件工具详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/plugins/{pluginId}/tools/{toolId}` | 更新插件工具 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/plugins/{pluginId}/tools/{toolId}` | 删除插件工具 |</span></span>\n<span class="line"><span>| POST | `/console/v1/plugins/{pluginId}/tools/{toolId}/test` | 测试插件工具 |</span></span>\n<span class="line"><span>| POST | `/console/v1/plugins/{pluginId}/tools/{toolId}/publish` | 发布插件工具 |</span></span>\n<span class="line"><span>| POST | `/console/v1/tools/{toolId}/enable` | 启用工具 |</span></span>\n<span class="line"><span>| POST | `/console/v1/tools/{toolId}/disable` | 禁用工具 |</span></span>\n<span class="line"><span>| POST | `/console/v1/tools/query-by-ids` | 按 ID 批量查询工具 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 13. MCP Server</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/mcp-servers`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/mcp-servers` | 注册 MCP Server |</span></span>\n<span class="line"><span>| PUT | `/console/v1/mcp-servers` | 更新 MCP Server |</span></span>\n<span class="line"><span>| GET | `/console/v1/mcp-servers` | MCP Server 分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/mcp-servers/{serverCode}` | 获取 MCP Server 详情（含工具列表） |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/mcp-servers/{serverCode}` | 删除 MCP Server |</span></span>\n<span class="line"><span>| POST | `/console/v1/mcp-servers/query-by-codes` | 按 code 批量查询 |</span></span>\n<span class="line"><span>| POST | `/console/v1/mcp-servers/debug-tools` | 调试 MCP 工具调用 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/mcp-servers`**</span></span>\n<span class="line"><span>- 入参：`McpServerDetail { code, name, url, transport, tools[], ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;String&amp;gt;` — serverCode</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/mcp-servers/debug-tools`**</span></span>\n<span class="line"><span>- 入参：`McpServerCallToolRequest { serverCode, toolName, arguments }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;McpServerCallToolResponse&amp;gt;` — `{ result, error }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 14. Agent Schema</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/agent-schemas`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/agent-schemas` | 创建 Agent Schema |</span></span>\n<span class="line"><span>| GET | `/console/v1/agent-schemas` | 全量列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/agent-schemas/page` | 分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/agent-schemas/{id}` | 获取详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/agent-schemas/{id}` | 更新 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/agent-schemas/{id}` | 删除 |</span></span>\n<span class="line"><span>| GET | `/console/v1/agent-schemas/search` | 按名称搜索 |</span></span>\n<span class="line"><span>| PATCH | `/console/v1/agent-schemas/{id}/enabled` | 启用 / 禁用 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 15. 文件上传</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/files`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/files/upload` | 上传文件（服务端转存） |</span></span>\n<span class="line"><span>| GET | `/console/v1/files/download` | 下载 / 预览文件 |</span></span>\n<span class="line"><span>| POST | `/console/v1/files/upload-policies` | 获取前端直传 OSS 策略 |</span></span>\n<span class="line"><span>| GET | `/console/v1/files/get-preview-url` | 获取文件预览链接 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/files/upload`**</span></span>\n<span class="line"><span>- 入参：`multipart/form-data`，`files[]`（多文件），`category`（分类）</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;UploadPolicy&amp;gt;&amp;gt;` — `{ url, key, ... }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/files/upload-policies`**</span></span>\n<span class="line"><span>- 入参：`WebUploadRequest { fileNames[], category }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;List&amp;lt;WebUploadPolicy&amp;gt;&amp;gt;` — 前端直传 OSS 所需签名信息</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/console/v1/files/download`**</span></span>\n<span class="line"><span>- 入参：`?filePath=xxx&amp;preview=true/false`</span></span>\n<span class="line"><span>- 返回：文件字节流（`void`，直接写入 response）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 16. API Key</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/api-keys`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/api-keys` | 创建 API Key |</span></span>\n<span class="line"><span>| GET | `/console/v1/api-keys` | 分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/api-keys/{id}` | 获取详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/api-keys/{id}` | 更新 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/api-keys/{id}` | 删除 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/console/v1/api-keys`**</span></span>\n<span class="line"><span>- 入参：`ApiKey { name, expireAt, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;String&amp;gt;` — 生成的 key 值（仅此次可见）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 17. 工作空间</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/workspaces`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/console/v1/workspaces` | 创建工作空间 |</span></span>\n<span class="line"><span>| GET | `/console/v1/workspaces` | 分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/workspaces/{workspaceId}` | 获取详情 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/workspaces/{workspaceId}` | 更新 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/workspaces/{workspaceId}` | 删除 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 18. 组件服务</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/component-servers`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| GET | `/console/v1/component-servers` | 组件分页列表 |</span></span>\n<span class="line"><span>| GET | `/console/v1/component-servers/app-publishable` | 可发布应用分页列表 |</span></span>\n<span class="line"><span>| POST | `/console/v1/component-servers` | 发布应用为组件 |</span></span>\n<span class="line"><span>| PUT | `/console/v1/component-servers/{code}` | 更新组件 |</span></span>\n<span class="line"><span>| DELETE | `/console/v1/component-servers/{code}` | 删除组件 |</span></span>\n<span class="line"><span>| GET | `/console/v1/component-servers/{code}/detail-by-code` | 按 code 获取组件详情 |</span></span>\n<span class="line"><span>| GET | `/console/v1/component-servers/{appId}/detail-by-appid` | 按 appId 获取组件详情 |</span></span>\n<span class="line"><span>| GET | `/console/v1/component-servers/{code}/query-refer` | 查询引用关系 |</span></span>\n<span class="line"><span>| GET | `/console/v1/component-servers/{appId}/query-config` | 查询组件配置 |</span></span>\n<span class="line"><span>| POST | `/console/v1/component-servers/query-by-codes` | 按 code 批量查询 |</span></span>\n<span class="line"><span>| GET | `/console/v1/component-servers/{code}/query-schema` | 获取组件 Schema |</span></span>\n<span class="line"><span>| POST | `/console/v1/component-servers/schema-by-codes` | 按 code 批量获取 Schema |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 19. Chat 对话（OpenAPI）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/api/v1/apps`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&amp;gt; 供外部 Agent 应用调用的标准对话接口。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| POST | `/api/v1/apps/chat/completions` | Agent 对话（流式 / 非流式） |</span></span>\n<span class="line"><span>| POST | `/api/v1/apps/workflow/completions` | 工作流同步执行 |</span></span>\n<span class="line"><span>| POST | `/api/v1/apps/workflow/async-completions` | 工作流异步执行 |</span></span>\n<span class="line"><span>| POST | `/api/v1/apps/workflow/stop-completions` | 停止异步任务 |</span></span>\n<span class="line"><span>| POST | `/api/v1/apps/workflow/async-results` | 查询异步执行结果 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/v1/apps/chat/completions`**</span></span>\n<span class="line"><span>- 入参：`AgentRequest { appId, messages[], stream, model, ... }`，`HttpServletResponse`</span></span>\n<span class="line"><span>- 返回：SSE 流（`stream=true`）或 JSON</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/v1/apps/workflow/async-completions`**</span></span>\n<span class="line"><span>- 入参：`WorkflowRequest { appId, inputs, ... }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;TaskRunResponse&amp;gt;` — `{ taskId }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**POST `/api/v1/apps/workflow/async-results`**</span></span>\n<span class="line"><span>- 入参：`AsyncResultRequest { taskId }`</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;AsyncResultResponse&amp;gt;` — `{ status, outputs, error }`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 20. OAuth2</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/oauth2`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| GET | `/oauth2/login/github` | 获取 GitHub OAuth 授权跳转 URL |</span></span>\n<span class="line"><span>| GET | `/oauth2/callback/github` | GitHub OAuth 回调，完成登录 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/oauth2/callback/github`**</span></span>\n<span class="line"><span>- 入参：`?code=xxx`（GitHub 回调 code）</span></span>\n<span class="line"><span>- 返回：重定向（写入 Cookie / 跳转前端）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 21. 系统</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/console/v1/system`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| GET | `/console/v1/system/global-config` | 获取系统全局配置 |</span></span>\n<span class="line"><span>| GET | `/console/v1/system/health` | 健康检查 |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/console/v1/system/global-config`**</span></span>\n<span class="line"><span>- 入参：无</span></span>\n<span class="line"><span>- 返回：`Result&amp;lt;GlobalConfig&amp;gt;` — 前端所需全局配置项</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**GET `/console/v1/system/health`**</span></span>\n<span class="line"><span>- 入参：无</span></span>\n<span class="line"><span>- 返回：`&quot;ok&quot;`（纯字符串）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 22. 代码生成器（Graph Studio）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Base path：** `/graph-studio/api`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 方法 | 路径 | 说明 |</span></span>\n<span class="line"><span>|------|------|------|</span></span>\n<span class="line"><span>| — | `/graph-studio/api/app/**` | Graph 应用管理（实现 AppAPI 接口） |</span></span>\n<span class="line"><span>| — | `/graph-studio/api/dsl/**` | DSL 导入导出（实现 DSLAPI 接口） |</span></span>\n<span class="line"><span>| — | `/graph-studio/api/run/**` | 运行 Graph（实现 RunnerAPI 接口） |</span></span>\n<span class="line"><span>| POST | `/starter.zip` 等 | 代码工程下载（继承 Spring Initializr） |</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&amp;gt; 此模块基于 Spring Initializr 框架扩展，具体路由由框架约定，接收 `GraphProjectRequest` 生成 Spring AI Alibaba 工程骨架。</span></span></code></pre></div><p><strong>常见坑</strong>：</p><p>第一个坑，AI 有时候会漏扫。Spring AI Alibaba Admin 的 Controller 分散在 <code>server-core</code>、 <code>server-openapi</code>、 <code>server-runtime</code> 几个模块里。你要在提示词里顺手提一句“项目是多模块的，每个 server 子模块下都可能有 Controller”。第一版出来一旦发现数量少得可疑，直接问一句“你扫了几个模块？有没有漏？”，AI 会补回来。</p><p>第二个坑，AI 可能把内部 RPC 接口和 REST 接口混在一起。Spring AI Alibaba Admin 里有些是对外 REST，有些是给 SDK 或 Agent 用的内部接口。让 AI 在清单里区分“对外”和“内部”两类。</p><p>第三个坑，返回结构写得太粗。AI 有时候写“返回 Prompt 对象”就完事了。这不够，至少要告诉你“返回一个 Prompt 列表还是单个 Prompt，有没有包装成 <code>Result&amp;lt;&gt;</code> 这种统一响应结构”。不够的话让它再细化一层。</p><h2 id="资产-2-数据模型说明" tabindex="-1">资产 2：数据模型说明 <a class="header-anchor" href="#资产-2-数据模型说明" aria-label="Permalink to &quot;资产 2：数据模型说明&quot;">​</a></h2><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看项目的 entity 类、DTO、数据库建表 SQL，给我梳理核心数据模型。</span></span>\n<span class="line"><span>每个模型列出字段、类型、一句话说明。标出主键、外键、枚举值。</span></span>\n<span class="line"><span>关键模型之间的关系画一张简单的 ER 图。保存到 docs/data-model.md 和 docs/data-model-er.svg。</span></span></code></pre></div><p><strong>关键点</strong>：</p><ul><li><p><strong>三个数据源一起看</strong>：entity 类（Java 层的 model）、DTO（传输层的 model）、建表 SQL（DB 层的 model）。三者不完全一致是常态，比如 entity 有的字段 DTO 里不暴露，DTO 有的字段是两个 entity 的组合。让 AI 三边对照。</p></li><li><p>“标出主键、外键、枚举值”这三个是数据模型的 <strong>硬信息</strong>。主键告诉你每个表怎么定位一条记录，外键告诉你表之间怎么关联，枚举告诉你某些字段的取值范围（比如 Prompt 的状态、Experiment 的运行状态）。这三个是改造时最容易踩坑的地方。</p></li><li><p>让 AI 同时产出 Markdown 说明和一张 ER 图。前者适合精确查找（PromptTemplate 表有哪些字段），后者适合整体把握（这几个表是怎么关联的）。</p></li></ul><p>生成的 ER 图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976182/730cef482effc5f8edcac7a915581711.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976182/730cef482effc5f8edcac7a915581711.png" alt=""></a></p><p><strong>常见坑</strong>：</p><p>第一个坑，AI 可能只看 Java 层的 entity，忽略建表 SQL。这样拿到的字段可能和数据库实际表不一致。比如 JPA 的 <code>@Transient</code> 字段在 entity 里有、DB 里没有，反过来 DB 有一些字段没映射到 entity 里。让 AI <strong>以 DB 层为准</strong>，entity 和 DTO 作为参照。</p><p>第二个坑，AI 可能把 DTO 和 entity 混成一个说明。这两种 model 的职责完全不同：entity 是持久层的映射，DTO 是传输层的契约。放一起说你会晕。让 AI 分开， <strong>entity 一份、DTO 一份</strong>，分别说清楚。</p><p>第三个坑，ER 图里容易漏关系。有些关系不通过外键表达，是通过业务代码维护的“逻辑关联”（比如 <code>prompt_id</code> 是某个字段，但 DB 里没建外键约束）。让 AI 除了看 DDL，也扫一下代码里 <code>findBy</code> 之类的查询方法，把隐式关系补上。</p><h2 id="五份资产怎么用" tabindex="-1">五份资产怎么用 <a class="header-anchor" href="#五份资产怎么用" aria-label="Permalink to &quot;五份资产怎么用&quot;">​</a></h2><p>画完 08 讲的三张图、做完 09 讲的两份清单， <code>docs/</code> 目录现在有五份东西：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>\n<span class="line"><span>├── architecture.svg      ← 架构图</span></span>\n<span class="line"><span>├── module-deps.svg       ← 模块图</span></span>\n<span class="line"><span>├── external-deps.svg     ← 依赖图</span></span>\n<span class="line"><span>├── api-list.md           ← 接口清单</span></span>\n<span class="line"><span>└── data-model.md + data-model-er.svg  ← 数据模型</span></span></code></pre></div><p>这五份资产不是摆在目录里吃灰，是后面每一讲的查询入口。</p><ul><li><p>10 讲写 CLAUDE.md，会把这五份资产引用进去，让 AI 每次启动都能快速定位项目的门面和根基。</p></li><li><p>13 讲让 AI 搞编译运行，需要对照“依赖图”确认中间件是不是都启动了。</p></li><li><p>14 讲建护栏，需要对照“接口清单”决定哪些接口要加集成测试，对照“数据模型”决定哪些表要加 characterization test。</p></li><li><p>第四部分做需求改造时，选一个接口改，你第一件事就是翻“接口清单”看当前长什么样、翻“数据模型”看字段关系，再动手。</p></li></ul><p><strong>摸清一个项目的核心产出就是这五份资产</strong>。它们不需要多漂亮，只需要够你和 AI 共同作为后续工作的输入就行。</p><h2 id="接口清单和数据模型之间的-校对" tabindex="-1">接口清单和数据模型之间的“校对” <a class="header-anchor" href="#接口清单和数据模型之间的-校对" aria-label="Permalink to &quot;接口清单和数据模型之间的“校对”&quot;">​</a></h2><p>还有一件事值得多说一句。 <strong>接口清单和数据模型这两份资产之间应该是自洽的</strong>。如果你发现接口清单里某个 API 返回 <code>PromptTemplate</code>，但数据模型里根本找不到 <code>PromptTemplate</code> 这个实体， <strong>说明两份资产有一份是错的</strong>。</p><p>这种不自洽在 AI 梳理的时候经常出现。AI 可能在接口清单里保留了老的类名，但数据模型里用了 refactor 之后的新名字。或者反过来。</p><p><strong>两份资产做完一定要互相对一下</strong>。让 AI 做一次校对：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对照 docs/api-list.md 和 docs/data-model.md，看接口里提到的每个实体在数据模型里是不是都有定义。</span></span>\n<span class="line"><span>有不一致的地方列出来。</span></span>\n<span class="line"><span>然后验证不一致的地方并修复。</span></span></code></pre></div><p>AI 会扫一遍，列出不一致点。你再让它修正。 <strong>修正完的两份资产才是可信的</strong>。这个“互相校对”的动作在 11 讲 SKILL.md 会固化成一个可复用的模板，到时候每次更新任何一份资产都触发一次校对，防止资产之间慢慢漂移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲产出了两份新资产：REST 接口清单和核心数据模型说明。</p><ol><li><p>两份资产要一起做，因为接口是项目的门面、数据是项目的根基，它们互相绑定。接口的参数返回是数据模型的映射，数据模型的变化会倒逼接口变化。做改造的时候这两份资产是你的导航地图。</p></li><li><p>提示词的关键是 <strong>让 AI 读真实文件</strong>。接口清单让它扫所有 Controller，数据模型让它综合看 entity、DTO、建表 SQL。不让它读代码就会脑补。</p></li><li><p>做完互相校对。接口里提到的实体在数据模型里要能找到，反过来也一样。这个自洽性是资产可信的前提。</p></li></ol><p>到这里 <code>docs/</code> 里已经有五份资产了。加上下一讲我们要写的 CLAUDE.md，项目的“脑图”就基本成型。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你手上项目的 Controller 如果让 AI 扫一遍，估计能扫出多少个接口？你自己能说清楚的有几个？差距在哪里？</p></li><li><p>你们团队现在有没有一份类似的“接口清单”文档？如果有，多久更新一次？如果没有，团队是怎么回答“我们有哪些对外接口”这个问题的？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>',51)])])}const v=n(l,[["render",i]]);export{u as __pageData,v as default};
